import React, { useState, useEffect, useMemo } from 'react';

// --- Helper Components & Icons ---

const InfoIcon = ({ title }) => (
    <span title={title}>
        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', cursor: 'help' }}>
            <circle cx="12" cy="12" r="10"></circle>
            <line x1="12" y1="16" x2="12" y2="12"></line>
            <line x1="12" y1="8" x2="12.01" y2="8"></line>
        </svg>
    </span>
);

const EditIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#495057' }}>
        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
    </svg>
);

const SaveIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
        <polyline points="17 21 17 13 7 13 7 21"></polyline>
        <polyline points="7 3 7 8 15 8"></polyline>
    </svg>
);

// --- Main Component ---

export default function PerStudentAllocationTab({ onAllocationChange }) {
    // --- State Management ---
    const [numberOfStudents, setNumberOfStudents] = useState(100);
    const [adminLoading, setAdminLoading] = useState(0.0);
    const [details, setDetails] = useState('');
    const [allocations, setAllocations] = useState([
        { role: 'Subject Coordinator', marking: 0, consultation: 0.0025, coordination: 0.00125 },
        { role: 'Assistant subject coordinator', marking: 0, consultation: 0, coordination: 0.00375 },
        { role: 'Exam marker', marking: 0.01, consultation: 0, coordination: 0 },
        { role: 'Tutor', marking: 0.01, consultation: 0.0025, coordination: 0 }
    ]);
    const [errors, setErrors] = useState({});
    const [lastSaved, setLastSaved] = useState(null);

    // State for inline editing in the table
    const [editingIndex, setEditingIndex] = useState(null);
    const [tempAllocation, setTempAllocation] = useState(null);
    const [editError, setEditError] = useState(null);

    // --- Memoized Calculations ---
    const BASE_RATE_PER_25 = 0.03;
    const totalRatePer25 = useMemo(() => BASE_RATE_PER_25 + adminLoading, [adminLoading]);
    const totalPerStudentAllocation = useMemo(() => (numberOfStudents > 0 ? (numberOfStudents / 25) * totalRatePer25 : 0), [numberOfStudents, totalRatePer25]);
    const currentDistributedSum = useMemo(() => allocations.reduce((total, item) => total + item.marking + item.consultation + item.coordination, 0), [allocations]);

    // --- Effects ---
    useEffect(() => {
        onAllocationChange?.(totalPerStudentAllocation);
    }, [totalPerStudentAllocation, onAllocationChange]);

    useEffect(() => {
        const newErrors = {};
        if (!Number.isInteger(numberOfStudents) || numberOfStudents <= 0) newErrors.numberOfStudents = 'Number of students must be a positive whole number.';
        if (adminLoading < 0 || adminLoading > 0.01) newErrors.adminLoading = 'Administrative loading must be between 0% and 1%.';
        if (adminLoading > 0 && !details.trim()) newErrors.details = 'Details are required to justify the administrative loading claim.';
        if (details && !/^[a-zA-Z0-9\s.,'-]*$/.test(details)) newErrors.details = 'Details cannot contain special characters.';
        if (currentDistributedSum > totalRatePer25) newErrors.table = `Maximum allocation exceeded. The sum (${(currentDistributedSum * 100).toFixed(3)}%) is more than the allowed rate of ${(totalRatePer25 * 100).toFixed(3)}%.`;
        setErrors(newErrors);
    }, [numberOfStudents, adminLoading, details, currentDistributedSum, totalRatePer25]);

    // --- Event Handlers ---
    const handleSave = () => {
        if (Object.keys(errors).length === 0) {
            setLastSaved(new Date());
            alert('Per-student allocation information saved successfully!');
        } else {
            alert('Please fix the errors before saving.');
        }
    };

    const handleEditClick = (index) => {
        setEditingIndex(index);
        setTempAllocation({ ...allocations[index] });
        setEditError(null);
    };

    const handleCancelClick = () => {
        setEditingIndex(null);
        setTempAllocation(null);
        setEditError(null);
    };

    const handleUpdateClick = () => {
        const otherAllocationsSum = allocations
            .filter((_, i) => i !== editingIndex)
            .reduce((sum, item) => sum + item.marking + item.consultation + item.coordination, 0);

        const newTotalSum = otherAllocationsSum + tempAllocation.marking + tempAllocation.consultation + tempAllocation.coordination;

        if (newTotalSum > totalRatePer25) {
            setEditError(`Update failed. New total sum (${(newTotalSum * 100).toFixed(3)}%) would exceed the maximum of ${(totalRatePer25 * 100).toFixed(3)}%.`);
            return;
        }

        const newAllocations = [...allocations];
        newAllocations[editingIndex] = tempAllocation;
        setAllocations(newAllocations);
        setEditingIndex(null);
        setTempAllocation(null);
        setEditError(null);
    };

    const handleTempChange = (field, value) => {
        const parsedValue = parseFloat(value);
        if (parsedValue < 0) return; // Prevent negative values
        setTempAllocation(prev => ({ ...prev, [field]: isNaN(parsedValue) ? 0 : parsedValue / 100 }));
    };

    // --- Render ---
    return (
        <div style={styles.container}>
            {/* --- Top Level Inputs --- */}
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="totalAllocation">Per-student Allocation <InfoIcon title={`Total workload allocation for all students. Calculated as (Number of students / 25) * (3% Base Rate + Admin Loading).`} /></label>
                <input style={{...styles.input, ...styles.readOnlyInput}} id="totalAllocation" type="text" value={`${(totalPerStudentAllocation * 100).toFixed(1)}%`} readOnly />
            </div>
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="numStudents">Number of students</label>
                <input style={styles.input} id="numStudents" type="number" value={numberOfStudents} onChange={(e) => setNumberOfStudents(parseInt(e.target.value, 10) || 0)} />
                 {errors.numberOfStudents && <span style={styles.errorText}>{errors.numberOfStudents}</span>}
            </div>
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="adminLoading">Administrative loading per 25 students <InfoIcon title="Optional loading for admin tasks, from 0% to 1%."/></label>
                <input style={styles.input} id="adminLoading" type="text" value={`${(adminLoading * 100).toFixed(1)}%`} onChange={(e) => setAdminLoading(parseFloat(e.target.value.replace('%', '')) / 100 || 0)} />
                 {errors.adminLoading && <span style={styles.errorText}>{errors.adminLoading}</span>}
            </div>
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="details">Details</label>
                <textarea style={styles.textarea} id="details" placeholder="If a claim is made, provide details." value={details} onChange={(e) => setDetails(e.target.value)}></textarea>
                {errors.details && <span style={styles.errorText}>{errors.details}</span>}
            </div>

            {/* --- Distribution Table --- */}
            <div style={styles.tableContainer}>
                <div style={styles.tableHeader}>
                    <h3 style={styles.tableTitle}>Per 25 students</h3>
                    <InfoIcon title="Distribution of the 3% base rate plus any administrative loading across different roles and tasks." />
                </div>
                {errors.table && <span style={{...styles.errorText, marginBottom: '1rem', display: 'block'}}>{errors.table}</span>}
                {editError && <span style={{...styles.errorText, marginBottom: '1rem', display: 'block'}}>{editError}</span>}
                <table style={styles.table}>
                    <thead>
                        <tr>
                            <th style={{...styles.th, ...styles.leftAlign, width: '10%'}}>Actions</th>
                            <th style={{...styles.th, ...styles.leftAlign}}>Staff Role</th>
                            <th style={{...styles.th, width: '15%'}}>Marking</th>
                            <th style={{...styles.th, width: '15%'}}>Consultation</th>
                            <th style={{...styles.th, width: '15%'}}>Coordination</th>
                        </tr>
                    </thead>
                    <tbody>
                        {allocations.map((item, index) => (
                            editingIndex === index ? (
                                <tr key={index}>
                                    <td style={{...styles.td, ...styles.leftAlign}}>
                                        <button onClick={handleUpdateClick} style={styles.actionButton}>Update</button>
                                        <button onClick={handleCancelClick} style={{...styles.actionButton, ...styles.cancelButton}}>Cancel</button>
                                    </td>
                                    <td style={{...styles.td, ...styles.leftAlign}}>{item.role}</td>
                                    <td style={styles.td}><input type="number" step="0.001" style={{...styles.tableInput, ...(editError ? styles.inputError : {})}} value={(tempAllocation.marking * 100).toFixed(3)} onChange={e => handleTempChange('marking', e.target.value)} /></td>
                                    <td style={styles.td}><input type="number" step="0.001" style={{...styles.tableInput, ...(editError ? styles.inputError : {})}} value={(tempAllocation.consultation * 100).toFixed(3)} onChange={e => handleTempChange('consultation', e.target.value)} /></td>
                                    <td style={styles.td}><input type="number" step="0.001" style={{...styles.tableInput, ...(editError ? styles.inputError : {})}} value={(tempAllocation.coordination * 100).toFixed(3)} onChange={e => handleTempChange('coordination', e.target.value)} /></td>
                                </tr>
                            ) : (
                                <tr key={index}>
                                    <td style={{...styles.td, ...styles.leftAlign}} onClick={() => handleEditClick(index)}><EditIcon /></td>
                                    <td style={{...styles.td, ...styles.leftAlign}}>{item.role}</td>
                                    <td style={styles.td}>{(item.marking * 100).toFixed(3)}%</td>
                                    <td style={styles.td}>{(item.consultation * 100).toFixed(3)}%</td>
                                    <td style={styles.td}>{(item.coordination * 100).toFixed(3)}%</td>
                                </tr>
                            )
                        ))}
                    </tbody>
                </table>
            </div>

            <div style={styles.buttonContainer}>
                <button style={styles.saveButton} onClick={handleSave}>
                    <SaveIcon />
                    Save
                </button>
                {lastSaved && <span style={styles.saveMessage}>Last saved: {lastSaved.toLocaleTimeString()}</span>}
            </div>
        </div>
    );
}

// --- Styles ---
const styles = {
    container: { fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif' },
    inputGroup: { display: 'flex', flexDirection: 'column', gap: '0.5rem', marginBottom: '1.5rem', maxWidth: '400px' },
    label: { color: '#212529', fontWeight: '600', fontSize: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' },
    input: { padding: '0.6rem 0.75rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '1rem', backgroundColor: '#fff' },
    readOnlyInput: { backgroundColor: '#f8f9fa', color: '#495057' },
    textarea: { padding: '0.75rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '1rem', minHeight: '80px', resize: 'vertical', width: '100%', maxWidth: 'unset' },
    errorText: { color: '#dc3545', fontSize: '0.8rem', marginTop: '0.25rem' },
    tableContainer: { marginTop: '2.5rem' },
    tableHeader: { display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' },
    tableTitle: { margin: 0, fontSize: '1.25rem', fontWeight: '600', color: '#212529' },
    table: { width: '100%', borderCollapse: 'collapse', borderSpacing: 0 },
    th: { padding: '0.75rem 1rem', textAlign: 'center', borderBottom: '1px solid #dee2e6', color: '#6c757d', fontWeight: '500', fontSize: '0.9rem', textTransform: 'uppercase' },
    td: { padding: '1rem', textAlign: 'center', borderBottom: '1px solid #dee2e6', color: '#212529', fontSize: '0.95rem' },
    leftAlign: { textAlign: 'left' },
    tableInput: { width: '80%', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', textAlign: 'center' },
    inputError: { borderColor: '#dc3545' },
    actionButton: { background: 'none', border: '1px solid #007bff', color: '#007bff', padding: '0.25rem 0.5rem', borderRadius: '4px', cursor: 'pointer', marginRight: '0.5rem' },
    cancelButton: { borderColor: '#6c757d', color: '#6c757d'},
    buttonContainer: { display: 'flex', alignItems: 'center', gap: '1rem', justifyContent: 'flex-start', marginTop: '2rem' },
    saveButton: { backgroundColor: '#212529', color: 'white', padding: '0.6rem 1.5rem', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '1rem' },
    saveMessage: { color: '#6c757d', fontSize: '0.9rem' }
};
